  (h_1 : (g ∘ Prod.snd) =O[𝓟 s ×ˢ l] f) {i : ι} (hi : i ∈ s) (C : ℝ)
  (hC : ∀ᶠ (x : ι × α) in 𝓟 s ×ˢ l, ‖(g ∘ Prod.snd) x‖ ≤ C * ‖f x‖) (t : Set (ι × α)) (htl : t ∈ 𝓟 s ×ˢ l)
